// Applies a G1 preset at runtime and runs the thermal governor. One per app (created by AppShell).
// Unity QualitySettings levels are generated by Kestrel > Setup Quality in the same order as
// data/quality.json, each with its own URP asset; this component switches level and then applies
// the device-dependent bits (render scale from dpr, frame rate, battery saver).
using System;
using UnityEngine;
using UnityEngine.Rendering.Universal;

namespace Kestrel.Game.Quality
{
    public sealed class QualityService : MonoBehaviour
    {
        const string PrefKey = "kh.quality.chosen";
        const string BatteryKey = "kh.quality.batterySaver";

        public QualityTable Table { get; private set; }
        public QualityGovernor Governor { get; private set; }
        public QualityPreset Current => Table.presets[Governor.Level];
        /// <summary>Particle budget for FX systems (plume, smoke). Read every spawn; may drop mid-flight.</summary>
        public int ParticleBudget => Current.particleBudget;
        public bool BatterySaver { get; private set; }
        public event Action<QualityPreset> Applied;

        public static QualityService Instance { get; private set; }

        void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
            Instance = this;
            Table = QualityTable.Load();
            int floor = Mathf.Max(0, Table.IndexOf(Table.governor.floor));
            int chosen = PlayerPrefs.HasKey(PrefKey)
                ? Mathf.Clamp(PlayerPrefs.GetInt(PrefKey), floor, Table.MaxSelectable())
                : Table.DefaultFor(SystemInfo.systemMemorySize);
            BatterySaver = PlayerPrefs.GetInt(BatteryKey, 0) == 1;
            Governor = new QualityGovernor(Table.ToGovernorConfig(), chosen, floor);
            Governor.Changed += (_, to) => Apply(to);
            // Editor/CLI captures run at editor frame rates (p95 > 20 ms) and stepped Medium -> Low mid-liftoff
            // (#129 probe). Step-downs are for device thermals only; -khGovernorInEditor opts back in.
            Governor.IgnoreFrameTimes = Application.isEditor && Array.IndexOf(Environment.GetCommandLineArgs(), "-khGovernorInEditor") < 0;
            QualityHold.Requested += OnHoldRequested;
            Apply(Governor.Level);
        }

        void OnHoldRequested(double seconds) => Governor?.HoldFor(seconds);
        void OnDestroy() { if (Instance == this) { QualityHold.Requested -= OnHoldRequested; Instance = null; } }

        void Update() => Governor.Tick(Time.unscaledDeltaTime);

        void OnApplicationPause(bool paused) { if (!paused) Governor.Reset(); }

        public void Choose(int level)
        {
            level = Mathf.Clamp(level, Governor.Floor, Table.MaxSelectable());
            PlayerPrefs.SetInt(PrefKey, level);
            Governor.SetChosen(level);
            Apply(Governor.Level);
        }

        public void SetBatterySaver(bool on)
        {
            BatterySaver = on;
            PlayerPrefs.SetInt(BatteryKey, on ? 1 : 0);
            Apply(Governor.Level);
        }

        void Apply(int level)
        {
            var p = Table.presets[level];
            if (QualitySettings.GetQualityLevel() != level && level < QualitySettings.names.Length)
                QualitySettings.SetQualityLevel(level, applyExpensiveChanges: true);

            float dpr = Screen.dpi > 0 ? Mathf.Max(1f, Screen.dpi / 160f) : 1f; // fallback only
#if UNITY_IOS && !UNITY_EDITOR
            dpr = DeviceScale();
#endif
            if (QualitySettings.renderPipeline is UniversalRenderPipelineAsset urp)
            {
                urp.renderScale = (float)QualityMath.RenderScale(p.renderScaleDprCap, dpr);
                urp.msaaSampleCount = p.msaa;
                urp.supportsHDR = p.hdr;
            }
            QualitySettings.vSyncCount = 0;
            Application.targetFrameRate = BatterySaver ? Table.defaults.batterySaverFps : p.targetFps;
            Applied?.Invoke(p);
            Debug.Log($"[Kestrel] quality {p.id} (renderScale≈{QualityMath.RenderScale(p.renderScaleDprCap, dpr):0.00}, {Application.targetFrameRate} fps, {p.particleBudget} particles)");
        }

#if UNITY_IOS && !UNITY_EDITOR
        // Screen px / pt. iOS points: screen width in px divided by the nominal 1x width is not exposed,
        // so infer from dpi buckets (326 → 2x, 401/460 → 3x, iPad 264 → 2x).
        static float DeviceScale() => Screen.dpi >= 400 ? 3f : 2f;
#endif
    }
}
